import {sources,strategies,levels,samplePlan} from './data.js';
const $=s=>document.querySelector(s);
function initialLanguage(){try{const pref=(localStorage.getItem('teachwithwhy-ui-language')||localStorage.getItem('etc-ui-language'));if(pref==='zh'||pref==='en')return pref;}catch{}return location.pathname.startsWith('/en')?'en':'zh';}
let lang=initialLanguage(),en=lang==='en';
const t=(zh,english)=>en?english:zh;
if(['/zh','/zh/','/en','/en/'].includes(location.pathname))history.replaceState(null,'','/'+location.search+location.hash);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function translate_names(){return {home:t('教學工作區','Workspace'),create:t('設計課堂活動','Design an activity'),compare:t('比較策略','Compare strategies'),plan:t('編輯活動','Edit activity'),reflect:t('課後回顧','Classroom reflection'),history:t('我的教學嘗試','My teaching trials'),library:t('研究與策略庫','Evidence library'),guide:t('使用說明','User guide'),about:t('關於與連線狀態','About & connection')};}
let names=translate_names();
const subjects={zh:['中國語文','英國語文','數學','科學','人文','其他'],en:['Chinese language','English language','Mathematics','Science','Humanities','Other']};
function translate_exampleProblems(){return t(['課堂提問總是由少數學生回答，其他學生很少表達想法。','小組討論由一兩人包辦，其他同學等着抄答案。','學生只給簡短答案，很少解釋原因或回應同學。'],['Only a few pupils answer questions while others rarely express their ideas.','One or two pupils do the group task while others wait to copy the answer.','Pupils give short answers without explaining reasons or responding to peers.']);}
let exampleProblems=translate_exampleProblems();
function translate_exampleGoals(){return t(['讓更多學生先形成自己的想法，並用不同方式參與。','讓每人提出一項貢獻，並能解釋小組答案怎樣形成。','讓學生用理由支持想法，並嘗試回應同學。'],['Help more pupils prepare their own ideas and participate in different ways.','Each pupil contributes and can explain how the shared response was formed.','Pupils support an idea with a reason and respond to a peer.']);}
let exampleGoals=translate_exampleGoals();
const blank=()=>({level:'upper',subject:subjects[lang][0],students:30,minutes:12,topic:'',problem:exampleProblems[0],goal:exampleGoals[0],constraints:['seats'],strategy:'think',consent:false});
function load(){try{let data=JSON.parse(localStorage.getItem('teachwithwhy-records-v2')||localStorage.getItem('evidence-classroom-v2')||localStorage.getItem('evidence-classroom-v1')||'[]');return Array.isArray(data)?data.filter(r=>r?.id&&r.draft&&r.plan).map(r=>({...r,plan:{origin:'template',...r.plan}})):[];}catch{return [];}}
let records=load(),draft=blank(),plan=null,activeId=null,view='home',busy=false,api={configured:false,provider:'deepseek',model:'deepseek-flash',liveSearch:true},apiChecked=false,toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function persist(){try{localStorage.setItem('teachwithwhy-records-v2',JSON.stringify(records));return true;}catch{toast(t('無法儲存，請先下載備份。','Storage unavailable. Please download a backup.'));return false;}}
function b(label,attrs='',variant=''){return `<button class="button ${variant}" ${attrs}>${label}</button>`;}
function heading(eyebrow,title,sub,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtext">${sub}</p></div>${extra}</div>`;}
function shell(){document.documentElement.lang=en?'en':'zh-Hant-HK';document.title=t('教得有據 · TeachWithWhy','TeachWithWhy · Teacher Workspace');$('#app').innerHTML=`<a class="skip" href="#main">${t('跳至主要內容','Skip to content')}</a><aside class="sidebar"><a href="/" class="brand"><span class="brand-symbol">教<span>↗</span></span><span>${t('教得有據','TeachWithWhy')}<small>${t('TEACHWITHWHY','RESEARCH · TRY · REFLECT')}</small></span></a><div class="workspace-label">${t('教師工作區','TEACHER WORKSPACE')} <span>HK</span></div><nav aria-label="${t('主要選單','Main navigation')}">${[['home','▦'],['create','＋'],['library','▤'],['history','◷'],['guide','?']].map(([id,icon])=>`<button data-nav="${id}"><span class="nav-icon">${icon}</span>${names[id]}${id==='history'?'<span id="saved-count" class="nav-count"></span>':''}</button>`).join('')}</nav><div class="sidebar-note"><span class="leaf">✳</span><strong>${t('讓研究走進課堂','Make evidence practical')}</strong><p>${t('每一次有依據的小嘗試，<br>都是教學改進的起點。','Small, informed trials.<br>Room to reflect and refine.')}</p></div><button data-nav="about" class="workspace-user"><span class="avatar">T</span><span>${t('我的教師工作區','My teacher workspace')}<small>${t('紀錄儲存於此瀏覽器','Records saved in this browser')}</small></span><span>↗</span></button></aside><div class="app-shell"><header class="topbar"><div id="breadcrumb"></div><div class="topbar-right"><span id="ai-status" class="prototype-badge"></span><button type="button" class="lang-link" data-language aria-label="${en?'切換至香港繁體中文':'Switch to English'}">${en?'香港繁體中文':'English'} ⇄</button><button class="text-button" data-nav="guide">${t('使用說明','User guide')} ↗</button></div></header><main id="main" tabindex="-1"></main><footer><span>${t('為香港小學及中學教師而設','For Hong Kong primary & secondary teachers')}</span><span>${t('研究有依據，教學有判斷。','Evidence informs. Teachers decide.')}</span></footer></div>`;$('#close-dialog').textContent=t('關閉','Close');updateStatus();}
function updateStatus(){if(!$('#ai-status'))return;$('#ai-status').innerHTML=`<i style="background:${api.configured?'#6b9366':'#aa9964'}"></i>${busy?t('正在檢索與生成…','Searching & generating…'):api.configured?t('AI 已設定','AI configured'):t('AI 尚未啟用 · 可用示例','AI not enabled · samples available')}`;}
async function checkStatus(){try{const r=await fetch('/api/status',{signal:AbortSignal.timeout(5000)});if(r.ok){const j=await r.json();if(typeof j.configured==='boolean')api=j;}}catch{}apiChecked=true;updateStatus();if(['about','guide'].includes(view))navigate(view,false);}
function navigate(v,focus=true){view=v;document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===(['compare','plan','reflect'].includes(v)?'create':v)));$('#breadcrumb').textContent=names[v];$('#saved-count').textContent=records.length;$('#main').innerHTML=({home:homeView,create:createView,compare:compareView,plan:planView,reflect:reflectView,history:historyView,library:libraryView,guide:guideView,about:aboutView})[v]();bindForms();updateStatus();if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
function steps(n){return `<div class="wizard-steps">${[names.create,names.compare,names.plan,names.reflect].map((s,i)=>`${i?'<b>→</b>':''}<span class="${i===n?'current':''}">0${i+1} ${s}</span>`).join('')}</div>`;}
function homeView(){return `${heading('A LITTLE EVIDENCE. A BETTER NEXT LESSON.',t('讓研究幫到下一堂。','Bring evidence into your next lesson.'),t('從真實課堂問題開始，設計一次有依據的教學嘗試。','Start with a real classroom challenge. Plan a small, informed teaching trial.'),b(t('設計新活動 ＋','New activity ＋'),'data-action="new"'))}<section class="hero"><div class="hero-copy"><p class="eyebrow">RESEARCH → PRACTICE → REFLECTION</p><h2>${t('有好的教學想法，<br>也要知道課堂上怎樣做。','Good teaching ideas.<br>A practical next step.')}</h2><p>${t('了解研究的依據及局限，配合班內學生的需要，<br>設計一個課堂上做得到、可以觀察學生反應的小嘗試。','Understand the evidence and its limits.<br>Adapt an idea to your class, then observe and refine.')}</p>${b(t('從我的課堂開始 ↗','Start with my classroom ↗'),'data-action="new"')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="paper-art"><b>▤</b><i></i><i></i><i></i><i></i></div><div class="action-art"><span>↗</span><i></i><i></i></div><div class="dot"></div><div class="art-label">FROM EVIDENCE TO ACTION</div></div></section><div class="guide-banner"><div><strong>${t('第一次使用？三分鐘了解整個流程。','First visit? Get started in three minutes.')}</strong><p>${t('用一個小學或中學例子，了解怎樣選策略、修改活動及記錄回顧。','Follow a primary or secondary example, from choosing a strategy to reviewing your trial.')}</p></div>${b(t('閱讀使用說明 →','Open the user guide →'),'data-nav="guide"','secondary')}</div><div class="steps-strip">${[t('描述課堂','Describe your class'),t('理解策略依據','Explore the evidence'),t('設計一次嘗試','Adapt an activity'),t('記錄與再調整','Reflect and refine')].map((s,i)=>`<div class="strip-step"><span class="step-dot">0${i+1}</span><strong>${s}</strong></div>`).join('')}</div><div class="section-title"><h2>${t('從熟悉的課堂情境開始','Start with a familiar challenge')}</h2><span class="tag">${t('小學 · 中學','PRIMARY · SECONDARY')}</span></div><div class="scenario-grid">${strategies.map((s,i)=>`<button class="scenario" data-example="${i}"><span class="scenario-icon">${['◌','▧','↗'][i]}</span><h3>${t(['次次都係同幾位同學答？','分咗組，最後都係一個人做？','答到問題，但講唔出原因？'][i],['The same few pupils answer?','Group work, but one pupil does it all?','Answers without explanations?'][i])}</h3><p>${s[lang].description}</p><span class="scenario-bottom"><span class="tag">${s[lang].label}</span><span>↗</span></span></button>`).join('')}</div><div class="bottom-grid"><section class="panel"><div class="section-title"><h2>${t('最近的教學嘗試','Recent teaching trials')}</h2><button class="text-button" data-nav="history">${t('查看全部','View all')} ↗</button></div>${records.length?records.slice(0,2).map(r=>`<div class="evidence-row"><div>${esc(r.title)}<small>${esc(levels[lang][r.draft.level])} · ${r.reflection?t('已回顧','Reviewed'):t('待課堂嘗試','Ready to try')}</small></div><button class="text-button" data-open="${esc(r.id)}">${t('開啟','Open')} →</button></div>`).join(''):`<div class="empty-small"><span class="empty-icon">◷</span><span>${t('儲存第一個活動，課後再帶着觀察回來。','Save your first activity, then return with classroom observations.')}</span></div>`}</section><section class="panel"><h2>${t('每個建議，都有來處','Every suggestion has a source')}</h2>${sources.map(s=>`<div class="evidence-row"><span>${s[lang].title}<small>EEF · ${s.updated}</small></span><button class="text-button" data-source="${s.id}">↗</button></div>`).join('')}</section></div>`;}
function createView(){return `${heading('01 / YOUR CLASSROOM',t('先說說，你的課堂。','Tell us about your classroom.'),t('目標、時間與課堂安排，決定活動怎樣設計。','Your goal, time and practical constraints shape the activity.'))}${steps(0)}<div class="layout-two"><form id="class-form" class="form-panel"><h2>${t('這一次，你想改善甚麼？','What would you like to improve?')}</h2><p class="subtext">${t('首個主題：課堂參與與討論。科目不限，請盡量提供具體課題。','First focus: classroom participation and discussion. Any subject; a specific topic helps.')}</p><h3 class="form-section-title">${t('課堂背景','Classroom context')}</h3><div class="field-grid"><div class="field"><label for="level">${t('年級範圍','Year group')}</label><select id="level" name="level">${Object.entries(levels[lang]).map(([k,v])=>`<option value="${k}" ${draft.level===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="subject">${t('科目／學習範疇','Subject / learning area')}</label><select id="subject" name="subject">${subjects[lang].map(s=>`<option ${s===draft.subject?'selected':''}>${s}</option>`).join('')}${!subjects[lang].includes(draft.subject)?`<option selected>${esc(draft.subject)}</option>`:''}</select></div></div><div class="field-grid"><div class="field"><label for="students">${t('學生人數','Number of pupils')}</label><input id="students" name="students" type="number" required min="2" max="60" value="${draft.students}"></div><div class="field"><label for="minutes">${t('活動時間（分鐘）','Activity length (minutes)')}</label><input id="minutes" name="minutes" type="number" required min="5" max="30" value="${draft.minutes}"></div></div><div class="field"><label for="topic">${t('課題（選填）','Lesson topic (optional)')}</label><input id="topic" name="topic" maxlength="100" placeholder="${t('例如：比較故事人物的選擇','For example: comparing characters’ choices')}" value="${esc(draft.topic)}"></div><div class="field"><label for="problem">${t('目前遇到的情況','Current classroom challenge')} *</label><textarea required id="problem" name="problem" maxlength="1200">${esc(draft.problem)}</textarea><small>${t('請勿輸入學生姓名、診斷報告或其他可識別資料。','Do not enter pupil names, diagnostic reports or other identifying details.')}</small></div><div class="field"><label for="goal">${t('希望學生做到甚麼？','What should pupils be able to do?')} *</label><textarea required id="goal" name="goal" maxlength="800">${esc(draft.goal)}</textarea></div><div class="field"><span class="field-label">${t('課堂安排','Practical constraints')}</span><div class="checks">${[['seats',t('不移動座位','Keep seats in place')],['no-tech',t('不使用電子裝置','No electronic devices')],['support',t('需要表達提示及句式','Language support needed')]].map(([k,v])=>`<label><input type="checkbox" name="constraints" value="${k}" ${draft.constraints.includes(k)?'checked':''}>${v}</label>`).join('')}</div></div><div class="field consent-box"><label><input type="checkbox" name="consent" ${draft.consent?'checked':''}>${t('如使用 AI，我同意將上述課堂描述傳送至網站所設定的模型及搜尋服務，並確認沒有加入可識別的學生資料。','If I use AI, I agree to send this classroom description to the configured model and search services, and confirm it contains no pupil-identifying information.')}</label><small>${t('只查看示例不會呼叫模型。活動輸出語言跟隨目前的中／英文網站版本。','Viewing samples does not call a model. Activity output follows the language of this site version.')}</small></div><div class="form-actions"><button type="button" class="text-button" data-nav="home">← ${names.home}</button><button class="button" type="submit">${t('比較策略 →','Compare strategies →')}</button></div></form><aside><div class="side-card"><span class="mini-label">START SMALL, LEARN SOMETHING</span><h3>${t('先選一個可觀察的目標','Choose one observable goal')}</h3><p>${t('不用重做整節課。先設計一次小嘗試，再觀察學生怎樣參與、解釋及回應。','You do not need to redesign the entire lesson. Start small and observe how pupils participate, explain and respond.')}</p><button class="inline-link" data-nav="guide">${t('看看完整使用例子 ↗','See a worked example ↗')}</button></div><div class="notice warm">${t('AI 可能出錯；核對來源並按學生需要修改後才使用。','AI can make mistakes. Check sources and adapt to pupil needs before use.')}</div></aside></div>`;}
function capture(){const f=$('#class-form');if(!f)return;const d=new FormData(f);for(const k of ['level','subject','topic','problem','goal'])draft[k]=String(d.get(k)||'');draft.students=Number(d.get('students'));draft.minutes=Number(d.get('minutes'));draft.constraints=d.getAll('constraints');draft.consent=d.has('consent');}
function summary(){return `<div class="summary-bar"><span class="tag green">${esc(levels[lang][draft.level])}</span><span>${esc(draft.subject)}</span><span>· ${draft.students} ${t('人','pupils')} · ${draft.minutes} ${t('分鐘','minutes')}</span><button class="text-button" data-nav="create">${t('修改條件 ↗','Edit context ↗')}</button></div>`;}
function compareView(){return `${heading('02 / EXPLORE THE EVIDENCE',t('選一個，值得嘗試的方法。','Choose a direction worth trying.'),t('先理解適用情況與局限，再由 AI 配合你的課堂設計活動。','Consider the fit and limitations, then let AI adapt an activity to your class.'))}${steps(1)}${summary()}${!api.configured?`<div class="notice warm">${t('目前未啟用 AI 服務。可以先體驗示例流程；「使用說明」列出啟用方式。','AI is not enabled yet. You can explore the sample workflow; setup guidance is in the user guide.')} <button class="inline-link" data-nav="guide">${names.guide} ↗</button></div>`:''}<div class="strategy-grid">${strategies.map(s=>`<article class="strategy-card"><span class="tag">${s[lang].label}</span><h2>${s[lang].name}</h2><p class="description">${s[lang].description}</p><div class="strategy-block"><strong>${t('何時考慮','When to consider it')}</strong><p>${s[lang].fit}</p></div><div class="strategy-block"><strong>${t('也要留意','Keep in mind')}</strong><p>${s[lang].caution}</p></div><button class="text-button" data-source="${s.source}">${t('查看研究依據與局限 ↗','Read the evidence and limits ↗')}</button>${b(t('聯網 AI 設計 →','Design with live AI →'),`data-ai="${s.id}" ${busy?'disabled':''}`)}<button class="text-button" data-sample="${s.id}">${t('先看示範活動','View a rule-based sample')}</button></article>`).join('')}</div><div id="ai-error" role="alert"></div><div class="notice">${t('研究中的平均結果不能直接套用到這次活動。每份 AI 草稿仍需教師核對。','Average research findings are not predictions for this activity. Every AI draft needs teacher review.')}</div>`;}
const errorText=code=>({AI_NOT_CONFIGURED:t('網站尚未設定 AI。管理員需要設定模型密鑰與試用碼。','AI is not configured. The owner must configure the model key and pilot code.'),ACCESS_CODE_REQUIRED:t('請到「連線狀態」輸入有效的試用碼。','Enter a valid pilot access code in Connection settings.'),CONSENT_REQUIRED:t('請返回課堂設定，確認 AI 資料傳送選項。','Return to classroom settings and confirm AI data processing consent.'),PROVIDER_AUTH:t('模型服務拒絕認證，請管理員檢查密鑰。','Model authentication failed. Ask the owner to check the key.'),PROVIDER_BALANCE:t('模型帳戶餘額不足。','The model account has insufficient credit.'),PROVIDER_RATE_LIMIT:t('模型服務繁忙，請稍後再試。','The model service is rate limited. Try again later.'),APP_RATE_LIMIT:t('已達本服務的暫時使用額度，請稍後再試。','The temporary usage limit has been reached. Try again later.'),PROVIDER_UNREACHABLE:t('無法連上模型或檢索服務，尚未產生 AI 方案。','The model or search service could not be reached. No AI plan was generated.'),INVALID_MODEL_OUTPUT:t('AI 回傳格式不完整，沒有用模板冒充結果。請重新嘗試。','The AI output was incomplete. It has not been replaced with a template. Please try again.'),INVALID_CITATION:t('AI 引用了無法核對的來源，這次結果未採用。','The AI cited an unverified source. This result was not accepted.'),NETWORK_ERROR:t('連線中斷或逾時，請稍後重試。','The connection failed or timed out. Please try again.'),INVALID_INPUT:t('請檢查人數、時間及必填內容。','Check the class size, activity length and required fields.')})[code]||t('AI 服務未能完成，請稍後重試。','The AI service could not complete the request. Please try again.');
async function aiRequest(action,extra={}){if(!draft.consent)throw new Error('CONSENT_REQUIRED');const code=sessionStorage.getItem('etc-pilot-code')||'';const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json','x-app-access-code':code},body:JSON.stringify({action,draft,lang,consent:true,...extra}),signal:AbortSignal.timeout(115000)});let data;try{data=await r.json();}catch{throw new Error('AI_NOT_CONFIGURED');}if(!r.ok)throw new Error(data.error||'NETWORK_ERROR');return data;}
async function generate(id){draft.strategy=id;if(!api.configured){toast(errorText('AI_NOT_CONFIGURED'));navigate('about');return;}busy=true;updateStatus();document.querySelectorAll('[data-ai],[data-sample]').forEach(x=>x.disabled=true);try{const result=await aiRequest('plan');plan=result.plan;activeId=null;busy=false;navigate('plan');toast(t('已完成聯網 AI 草稿，請核對後使用。','Live AI draft ready. Please review before use.'));}catch(e){busy=false;const node=$('#ai-error');if(node)node.innerHTML=`<div class="notice warm">${esc(errorText(e.message))} <button class="inline-link" data-nav="about">${t('連線狀態 ↗','Connection settings ↗')}</button></div>`;toast(errorText(e.message));document.querySelectorAll('[data-ai],[data-sample]').forEach(x=>x.disabled=false);updateStatus();}}
function getPlanSources(){return Array.isArray(plan?.sources)&&plan.sources.length?plan.sources:sources;}
function sourceMeta(s){const local=s[lang];return{title:local?.title||s.title||s.id,finding:local?.finding||'',scope:local?.scope||'',limit:local?.limit||'',url:s.url,updated:s.updated,kind:s.contentKind||'reviewed-summary'};}
function planView(){if(!plan)plan=samplePlan(draft,lang);const ai=plan.origin==='ai';return `${heading('03 / MAKE IT YOURS',esc(plan.title),t('編輯草稿、核對來源，再安排一次課堂嘗試。','Edit the draft, check its sources and plan a classroom trial.'),b(t('列印／另存 PDF ↗','Print / save as PDF ↗'),'data-action="print"','secondary'))}${steps(2)}${summary()}<div class="layout-two"><article class="form-panel"><span class="tag ${ai?'green':'orange'}">${ai?`AI · ${esc(plan.model)}`:t('示範活動 · 不是 AI 結果','Rule-based sample · not an AI result')}</span>${ai?`<p class="source-citation">${t('生成時間','Generated')}: ${esc(new Date(plan.generatedAt).toLocaleString(en?'en-HK':'zh-HK'))} · ${plan.search?.completed?t(`聯網檢索：${plan.search.count} 個合規來源`,`Live retrieval: ${plan.search.count} eligible sources`):t('未啟用即時檢索','Live retrieval disabled')}</p>`:''}<h2 style="margin-top:18px">${esc(draft.goal)}</h2><div class="notice">${esc(plan.support)}</div><div class="timeline">${plan.steps.map((s,i)=>`<div class="timeline-item"><div class="timeline-time">${s.minutes} ${t('分鐘','min')}<br>0${i+1}</div><div><h4>${esc(s.title)}</h4><textarea class="plan-edit" data-step="${i}" aria-label="${t('步驟','Step')} ${i+1}" maxlength="3500">${esc(s.text)}</textarea><div class="print-value" hidden>${esc(s.text)}</div></div></div>`).join('')}</div><div class="plan-section"><h3>${t('材料與準備','Materials & preparation')}</h3><p class="subtext">${esc(plan.materials)}</p></div><div class="plan-section"><h3>${t('先觀察甚麼？','What to observe')}</h3><ul class="observation-list">${(plan.observations||samplePlan(draft,lang).observations).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="plan-section"><label for="teacher-note" class="field-label">${t('我的調整與備註','My changes & notes')}</label><textarea id="teacher-note" class="plan-edit" maxlength="2500">${esc(plan.teacherNote)}</textarea><div class="print-value" hidden>${esc(plan.teacherNote)}</div></div><div class="plan-section"><h3>${t('研究依據與局限','Evidence & limitations')}</h3>${(plan.evidence||[]).map(e=>{const s=getPlanSources().find(a=>a.id===e.sourceId);return `<div class="evidence-note"><strong>${esc(sourceMeta(s||{}).title)}</strong><p>${esc(e.finding)}</p><p>${esc(e.limitation)}</p>${s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${t('核對原始來源 ↗','Check the original source ↗')}</a><div class="source-citation">${esc(s.url)}</div>`:''}</div>`;}).join('')}<p class="subtext">${t('活動步驟屬於產品／AI 改編，未經這些研究直接驗證。','The activity is a product / AI adaptation, not a directly validated intervention from these sources.')}</p>${(plan.cautions||[]).map(x=>`<div class="notice warm">${esc(x)}</div>`).join('')}${plan.timingAdjusted?`<div class="notice">${t('AI 時間分配已由系統調整至所選總時長，請核對可行性。','AI stage durations were adjusted to your selected total. Please check feasibility.')}</div>`:''}</div><div class="form-actions"><button class="text-button" data-nav="compare">← ${names.compare}</button><div style="display:flex;gap:9px;flex-wrap:wrap">${b(t('儲存活動','Save activity'),'data-action="save"')}${b(t('課後回顧 →','Classroom reflection →'),'data-action="reflect"','secondary')}</div></div></article><aside><div class="side-card"><span class="mini-label">TEACHERS DECIDE</span><h3>${t('把它變成你的活動','Make it your own')}</h3><p>${t('核對內容與依據；按照學生已有知識及表達需要調整。草稿與研究結論需要分開看。','Check the content and evidence, then adapt to prior knowledge and language needs. A generated draft is separate from a research finding.')}</p><button class="inline-link" data-nav="guide">${names.guide} ↗</button></div><div class="notice">${t('紀錄只存於此瀏覽器。請定期下載備份。','Records stay in this browser. Download backups regularly.')}</div></aside></div>`;}
function syncPlan(){if(!plan)return;document.querySelectorAll('[data-step]').forEach(x=>plan.steps[+x.dataset.step].text=x.value);if($('#teacher-note'))plan.teacherNote=$('#teacher-note').value;}
function save(quiet=false){syncPlan();const id=activeId||crypto.randomUUID(),old=records.find(r=>r.id===id),r={id,title:plan.title,draft:structuredClone(draft),plan:structuredClone(plan),reflection:old?.reflection||null,reflectionAI:old?.reflectionAI||null,notes:old?.notes||[],created:old?.created||new Date().toISOString(),updated:new Date().toISOString()};const prev=records;records=[r,...records.filter(x=>x.id!==id)];if(!persist()){records=prev;return false;}activeId=id;$('#saved-count').textContent=records.length;if(!quiet)toast(t('活動已儲存。','Activity saved.'));return true;}
function open(id,next='plan'){const r=records.find(x=>x.id===id);if(!r)return;draft=structuredClone(r.draft);plan=structuredClone(r.plan);activeId=id;navigate(next);}
function reflectView(){const r=records.find(x=>x.id===activeId),f=r?.reflection||{},ai=r?.reflectionAI;return `${heading('04 / REFLECT & REFINE',t('帶着觀察，回到這裏。','Return with your observations.'),t('具體記錄發生了甚麼，再決定下一次怎樣調整。','Record what happened, then decide what to refine.'))}${steps(3)}<div class="layout-two"><form id="reflection-form" class="form-panel"><span class="tag green">${esc(plan?.title)}</span><div class="field" style="margin-top:24px"><label for="lesson-date">${t('課堂日期','Lesson date')}</label><input id="lesson-date" name="date" type="date" required value="${esc(f.date||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()))}"></div><div class="field-grid"><div class="field"><label for="actual">${t('實際時間（分鐘）','Actual duration (minutes)')}</label><input type="number" id="actual" name="actual" min="1" max="180" required value="${esc(f.actual||draft.minutes)}"></div><div class="field"><label for="participation">${t('教師觀察的參與情況','Observed participation')}</label><select id="participation" name="participation">${[t('尚未能判斷','Not yet clear'),t('少數學生參與','A few pupils'),t('約一半學生參與','About half the class'),t('大部分學生參與','Most of the class')].map(v=>`<option ${v===f.participation?'selected':''}>${v}</option>`).join('')}</select></div></div>${[['observation',t('你觀察到甚麼？','What did you observe?')],['difficulty',t('哪裏遇到困難？','What was difficult?')],['next',t('下一次想怎樣調整？','What would you change next time?')]].map(([k,title])=>`<div class="field"><label for="${k}">${title}${k==='observation'?' *':''}</label><textarea id="${k}" name="${k}" maxlength="2000" ${k==='observation'?'required':''}>${esc(f[k]||'')}</textarea></div>`).join('')}<div class="notice">${t('一次觀察不能證明活動造成了某種改變。AI 只能提出待教師判斷的建議。','One observation does not show that an activity caused a change. AI suggestions require teacher judgement.')}</div><div class="form-actions"><button type="button" class="text-button" data-nav="plan">← ${names.plan}</button><button type="submit" class="button">${t('儲存回顧 ✓','Save reflection ✓')}</button></div><div style="margin-top:18px">${b(t('儲存並請 AI 建議下一步 ↗','Save & ask AI for next steps ↗'),'type="button" data-action="reflect-ai"','secondary')}</div>${ai?`<div class="plan-section"><h3>${t('AI 建議 · 非成效結論','AI suggestions · not an impact conclusion')}</h3>${['keep','adjust','uncertainty'].map((k,i)=>`<div class="evidence-note"><strong>${t(['值得保留','可作調整','仍不確定'][i],['Worth keeping','Possible adjustments','Still uncertain'][i])}</strong><ul>${ai.result[k].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}<p class="source-citation">${esc(ai.meta.model)} · ${esc(new Date(ai.meta.generatedAt).toLocaleString())}</p></div>`:''}</form><aside><div class="side-card"><h3>${t('具體，比好壞更有用','Specific beats good or bad')}</h3><p>${t('記下你看見、聽見的事，保留不同解釋。請勿加入學生身分資料。','Record what you saw or heard, and keep alternative explanations open. Do not include pupil-identifying information.')}</p></div></aside></div>`;}
function saveReflection(){const f=$('#reflection-form');if(!f.reportValidity())return false;const data=Object.fromEntries(new FormData(f));if(!data.observation.trim())return false;const r=records.find(x=>x.id===activeId);if(!r)return false;const prev=structuredClone(r);r.reflection=data;r.updated=new Date().toISOString();if(!persist()){Object.assign(r,prev);return false;}return true;}
async function reflectAI(){if(!saveReflection())return;const r=records.find(x=>x.id===activeId);if(!api.configured){toast(errorText('AI_NOT_CONFIGURED'));return;}if(!confirm(t('把本次回顧傳送至已設定的 AI 與搜尋服務，以取得調整建議？請先確認沒有學生身分資料。','Send this reflection to the configured AI and search services for suggestions? Confirm it contains no pupil-identifying information.')))return;draft.consent=true;busy=true;updateStatus();try{const result=await aiRequest('reflect',{reflection:r.reflection});r.reflectionAI={result:result.reflection,meta:result.meta};persist();busy=false;navigate('reflect');}catch(e){busy=false;toast(errorText(e.message));updateStatus();}}
function historyView(){return `${heading('MY TEACHING TRIALS',t('每一次嘗試，都留下線索。','Keep a record of each teaching trial.'),t('保存方案與回顧，保留調整教學的過程。','Save activities and reflections so you can revisit your decisions.'),b(t('新活動 ＋','New activity ＋'),'data-action="new"'))}<div class="notice">${t('紀錄只保存在目前瀏覽器，請定期下載備份。可以匯入本產品的 JSON 備份。','Records are stored in this browser only. Download backups regularly; you can also import this product’s JSON backups.')}</div><div class="history-toolbar">${b(t('下載全部備份 ↓','Download all records ↓'),'data-action="export"','secondary')}<label class="button secondary" for="import-file">${t('匯入備份 ↑','Import backup ↑')}</label><input id="import-file" type="file" accept="application/json,.json" hidden></div>${records.length?`<div class="history-grid">${records.map(r=>`<article class="history-card"><span class="tag ${r.reflection?'green':'orange'}">${r.reflection?t('已完成回顧','Reviewed'):t('待課堂嘗試','Ready to try')}</span><h2>${esc(r.title)}</h2><p>${esc(levels[lang][r.draft.level])} · ${r.draft.minutes} ${t('分鐘','minutes')} · ${r.plan.origin==='ai'?'AI':t('示例','Sample')}</p><p>${esc(r.draft.goal)}</p>${r.reflection?`<div class="reflection-summary">${esc(r.reflection.next||r.reflection.observation)}</div>`:''}<div class="history-actions">${b(t('開啟活動 →','Open activity →'),`data-open="${esc(r.id)}"`,'secondary')}<button class="text-button" data-review="${esc(r.id)}">${names.reflect}</button><button class="danger-button" data-delete="${esc(r.id)}">${t('刪除','Delete')}</button></div></article>`).join('')}</div>`:`<div class="empty-state"><h2>${t('從第一次小嘗試開始。','Start with your first small trial.')}</h2><p>${t('儲存活動後，它會顯示在這裏。','Saved activities will appear here.')}</p>${b(t('設計第一個活動 →','Design your first activity →'),'data-action="new"')}</div>`}`;}
function libraryView(){return `${heading('EVIDENCE LIBRARY',t('每個建議，都可以追溯。','Know where a suggestion comes from.'),t('固定研究庫目前整理兩份綜述；AI 模式會另外標示即時檢索來源。','The curated library contains two reviews. AI outputs separately identify live-retrieved sources.'))}<div class="library-grid">${sources.map(s=>`<article class="library-card"><span class="tag green">EEF · ${t('證據綜述','Evidence review')}</span><h2>${s[lang].title}</h2><p>${s[lang].finding}</p><div class="library-meta">${t('來源更新','Source updated')}: ${s.updated}<br>${t('摘要核對','Summary reviewed')}: ${s.reviewed}</div><span class="tag orange">${s[lang].strength}</span><div style="margin-top:23px">${b(t('閱讀範圍及局限 ↗','Read scope and limits ↗'),`data-source="${s.id}"`,'secondary')}</div></article>`).join('')}</div><div class="notice">${t('研究確定性是原綜述的評價，並非對本工具擬定活動的評分。','Evidence-security labels belong to the source review, not to activities generated by this tool.')}</div>`;}
function guideView(){return `${heading('USER GUIDE',t('從第一個問題，到下一次調整。','From a first question to your next refinement.'),t('主要為電腦使用而設，也可在手機或平板查看。','Designed primarily for desktop use; also accessible on tablets and phones.'),`<a class="button secondary" href="/docs/user-guide-${lang}.md" download>${t('下載說明書 ↓','Download guide ↓')}</a>`)}<div class="guide-layout"><aside class="guide-index"><strong>${t('頁面目錄','On this page')}</strong>${[t('三分鐘開始','Start in three minutes'),t('小學與中學例子','Worked examples'),t('AI 與聯網狀態','AI & live search'),t('保存、列印與備份','Save, print & backup'),t('常見問題','Frequently asked questions')].map((x,i)=>`<a href="#guide-${i}">${String(i+1).padStart(2,'0')} ${x}</a>`).join('')}</aside><article class="about-prose guide-prose"><section id="guide-0"><h2>${t('三分鐘開始','Start in three minutes')}</h2><ol><li>${t('在教學工作區選一個情境，或按「設計新活動」。','Choose a scenario on the workspace, or select “New activity”.')}</li><li>${t('填寫年級、課題、學生人數、活動時間、困難與目標。','Enter the year group, topic, class size, time, challenge and goal.')}</li><li>${t('比較策略，查看適用條件、研究範圍與局限。','Compare strategies and read the evidence, scope and limitations.')}</li><li>${t('先按「查看示範活動」體驗；已啟用 AI 的網站可按「聯網 AI 設計」。','Use “View a rule-based sample” to explore. If AI is enabled, choose “Design with live AI”.')}</li><li>${t('修改步驟並儲存。上課後回來記錄觀察及下一次調整。','Edit and save the activity. After teaching, return to record observations and next steps.')}</li></ol>${b(t('用高小例子試一次 →','Try an upper-primary example →'),'data-guide-example="upper"')} <button class="text-button" data-guide-example="junior">${t('試試初中例子 ↗','Try a junior-secondary example ↗')}</button></section><section id="guide-1"><h2>${t('小學與中學例子','Worked examples')}</h2><p><strong>${t('高小中文：故事人物的選擇','Upper-primary language: a character’s choices')}</strong><br>${t('30 人，12 分鐘。目標：每位學生先提出一個想法，再用一個理由解釋人物的選擇。可選「先諗一諗，再分享」，容許關鍵詞或圖示。','30 pupils, 12 minutes. Goal: each pupil prepares an idea and one reason for a character’s choice. Try “Think, then share”, allowing keywords or drawings.')}</p><p><strong>${t('初中科學：比較兩個解釋','Junior-secondary science: comparing explanations')}</strong><br>${t('32 人，15 分鐘。目標：比較兩個現象解釋，指出各自依據及未知之處。可選「講諗法，也講理由」，由教師提供已核對的現象材料。','32 pupils, 15 minutes. Goal: compare two explanations, identify their evidence and note uncertainty. Try “Give an idea and a reason”, using teacher-checked lesson material.')}</p><p>${t('初小可用指認、畫圖及短句；高中可增加依據、假設及反例比較。學段不等於個別學生能力，仍需教師調整。','Lower-primary pupils may use pointing, drawing or short sentences. Senior-secondary tasks may compare evidence, assumptions and counterexamples. Year group does not determine individual ability.')}</p></section><section id="guide-2"><h2>${t('AI 與聯網狀態','AI & live search')}</h2><p>${t('畫面上方顯示 AI 是否已設定。AI 模式會將課堂描述傳送至所設定的供應商，檢索資料後擬定活動；輸出會列出模型、時間及來源。','The top bar shows whether AI is configured. AI mode sends the classroom description to the configured provider, retrieves sources and generates an activity. Outputs identify the model, time and sources.')}</p><p>${t('示例模式使用固定策略與規則，不會呼叫 AI。呼叫失敗會明確顯示錯誤，不會把示例冒充 AI 結果。','Sample mode uses fixed strategies and rules without calling AI. Errors are shown explicitly; samples are never presented as AI results.')}</p><p>${t('即時搜尋不保證找到最新或最適合的研究。摘要與搜尋片段不等於已審閱全文；請核對研究對象、指標及限制。','Live search does not guarantee the newest or best-matched research. A summary or snippet is not a reviewed full text. Check the population, outcomes and limitations.')}</p>${b(t('查看連線與輸入試用碼 ↗','Check connection / enter pilot code ↗'),'data-nav="about"','secondary')}</section><section id="guide-3"><h2>${t('保存、列印與備份','Save, print & backup')}</h2><ul><li>${t('按「儲存活動」保存到目前瀏覽器，不會自動同步到其他裝置。','“Save activity” stores it in this browser; it does not sync across devices.')}</li><li>${t('在活動頁按「列印／另存 PDF」，選擇瀏覽器的 PDF 列印目的地。','Use “Print / save as PDF” and choose the browser’s PDF destination.')}</li><li>${t('在「我的教學嘗試」下載 JSON 備份，也可以匯入同一格式的備份。','Download JSON backups in “My teaching trials”, and import the same format when needed.')}</li><li>${t('切換語言不會翻譯已儲存的原始活動。需要新語言輸出時，重新建立活動。','Switching the interface language does not translate saved activities. Create a new activity for a different output language.')}</li></ul></section><section id="guide-4"><h2>${t('常見問題','Frequently asked questions')}</h2>${[[t('為甚麼不能使用 AI？','Why is AI unavailable?'),t('網站管理員尚未設定有效模型密鑰，或你需要先輸入試用碼。模型帳戶還需有可用額度。','The owner may not have configured a valid model key, or you may need a pilot code. The model account also needs available credit.')],[t('可以直接用於上課嗎？','Can I use the output directly?'),t('先核對內容及來源，按學生需要修改。AI 草稿不等於已驗證的教學安排。','Check the content and sources, then adapt it to pupils. An AI draft is not a validated intervention.')],[t('有沒有證明學生進步？','Does this prove pupils improved?'),t('沒有。教師回顧是局部觀察，不能直接建立因果或代表全班學習成效。','No. Teacher reflections are local observations, not causal evidence or a complete measure of learning.')],[t('會收集學生資料嗎？','Does it collect pupil data?'),t('不需要學生帳號。不要加入姓名或身分資料。AI 模式會傳送你填寫的描述與回顧，供應商的保留政策另行適用。','No pupil accounts are needed. Do not enter names or identifying information. AI mode sends your descriptions and reflections; provider retention policies apply.')]].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section></article></div>`;}
function aboutView(){return `${heading('CONNECTION & ABOUT',t('連線狀態與使用設定','Connection status & settings'),t('教師輸入試用碼即可使用已設定的 AI，無需提供模型密鑰。','Teachers use a pilot access code for the configured AI service; they do not enter model API keys.'))}<article class="about-prose"><h2>${t('目前服務狀態','Service status')}</h2><p><span class="tag ${api.configured?'green':'orange'}">${api.configured?t('AI 已設定，尚需有效試用碼','AI configured; valid pilot code required'):t('AI 尚未設定','AI not configured')}</span></p><p>${t('模型','Model')}: <strong>${esc(api.model)}</strong><br>${t('即時檢索','Live retrieval')}: ${api.liveSearch?t('設定為啟用','Enabled in settings'):t('設定為停用','Disabled in settings')}</p><p>${t('設定狀態不代表已完成連線驗證；真正呼叫成功後，活動會標示模型與生成時間。','Configuration status is not a successful connection test. A completed AI activity records the actual model and generation time.')}</p><form id="access-form"><div class="field"><label for="access-code">${t('教師試用碼（不是 API 密鑰）','Teacher pilot code (not an API key)')}</label><input id="access-code" type="password" autocomplete="off" minlength="12" placeholder="${t('由網站管理員提供','Provided by the site owner')}" value="${esc(sessionStorage.getItem('etc-pilot-code')||'')}"><small>${t('只保留於目前瀏覽器分頁工作階段。','Stored only for the current browser session.')}</small></div>${b(t('儲存試用碼','Save pilot code'),'type="submit"')} <button type="button" class="text-button" data-action="clear-code">${t('清除','Clear')}</button> <button type="button" class="text-button" data-action="refresh-status">${t('重新檢查狀態','Refresh status')}</button></form><h2>${t('紀錄與私隱','Records & privacy')}</h2><p>${t('活動及回顧保存在此瀏覽器。AI 功能會將你選擇提交的內容傳送至模型與搜尋服務；請勿加入學生身分資料。正式使用前請確認機構政策與供應商資料處理安排。','Activities and reflections stay in this browser. AI functions send the content you choose to submit to the model and search services. Exclude pupil-identifying details and check your institution’s policy and provider data terms before formal use.')}</p><details><summary>${t('網站管理員：怎樣啟用 AI 與發佈？','Site owner: enabling AI and deployment')}</summary><p>${t('後端支援 DeepSeek 與 OpenAI。請在 Vercel 的私密環境變量設定模型 API 密鑰，以及至少 12 個字元的 APP_ACCESS_CODE，再重新部署。不要把密鑰填在網頁、說明書或公開 GitHub。','The backend supports DeepSeek and OpenAI. In Vercel’s private environment variables, configure the model API key and an APP_ACCESS_CODE of at least 12 characters, then redeploy. Never put API keys in this page, documentation or public GitHub.')}</p><p><a href="https://api-docs.deepseek.com/" target="_blank" rel="noopener noreferrer">DeepSeek API documentation ↗</a></p><p>${t('目前推薦預設別名 deepseek-flash（官方文件於 2026-11-03 對應 V4.1-Flash-1017）；可按帳戶可用模型調整。API 按用量收費，模型開放權重不等於託管 API 免費。','The prepared default is deepseek-flash (official docs on 2026-11-03 map it to V4.1-Flash-1017). Adjust to models available to your account. Hosted API usage is billed; open weights do not imply a free hosted API.')}</p></details><h2>${t('版本與證據','Version & evidence')}</h2><p>v0.2 · ${t('雙語介面、使用說明、示例模式與真實模型後端。來源綜述不構成官方認證或背書。','Bilingual interface, user guide, sample mode and a real provider backend. Source reviews do not imply official endorsement.')}</p></article>`;}
function showSource(id){const s=sources.find(x=>x.id===id);if(!s)return;const d=s[lang];$('#source-content').innerHTML=`<p class="eyebrow">EEF / EVIDENCE NOTE</p><h2 id="source-title">${d.title}</h2><span class="tag orange">${d.strength}</span>${[[t('研究發現','Findings'),d.finding],[t('研究範圍','Scope'),d.scope],[t('局限','Limitations'),d.limit]].map(([k,v])=>`<h3>${k}</h3><p>${v}</p>`).join('')}<p class="source-citation">${t('來源更新','Source updated')}: ${s.updated}<br>${t('摘要核對','Summary reviewed')}: ${s.reviewed}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${t('核對原始來源 ↗','Check the original source ↗')}</a>`;$('#source-dialog').setAttribute('aria-labelledby','source-title');$('#source-dialog').showModal();}
function exportRecords(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({product:'TeachWithWhy',version:2,exported:new Date().toISOString(),records},null,2)],{type:'application/json'}));a.href=url;a.download='teachwithwhy-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('備份下載已開始。','Backup download started.'));}
function validImport(r){
 const strings=a=>Array.isArray(a)&&a.length<=20&&a.every(x=>typeof x==='string');
 if(!r||typeof r.id!=='string'||r.id.length>100||typeof r.title!=='string'||!r.draft||!Object.hasOwn(levels.en,r.draft.level)||!Number.isInteger(r.draft.students)||r.draft.students<2||r.draft.students>60||!Number.isInteger(r.draft.minutes)||r.draft.minutes<5||r.draft.minutes>30||!strings(r.draft.constraints)||!['think','joint','reason'].includes(r.draft.strategy)||!r.plan||typeof r.plan.title!=='string'||!Array.isArray(r.plan.steps)||!r.plan.steps.length||r.plan.steps.length>10||!r.plan.steps.every(s=>s&&typeof s.title==='string'&&typeof s.text==='string'&&Number.isInteger(s.minutes)&&s.minutes>0))return false;
 if(r.plan.observations&&!strings(r.plan.observations))return false;
 if(r.plan.cautions&&!strings(r.plan.cautions))return false;
 if(r.plan.evidence&&(!Array.isArray(r.plan.evidence)||r.plan.evidence.some(e=>!e||typeof e.sourceId!=='string'||typeof e.finding!=='string'||typeof e.limitation!=='string')))return false;
 if(r.plan.sources&&(!Array.isArray(r.plan.sources)||r.plan.sources.length>20||!r.plan.sources.every(s=>{try{const u=new URL(s.url);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}})))return false;
 if(r.reflection&&(!r.reflection.observation||typeof r.reflection.observation!=='string'))return false;
 if(r.reflectionAI&&!['keep','adjust','uncertainty'].every(k=>strings(r.reflectionAI.result?.[k])))return false;
 return true;
}
async function importRecords(file){if(!file)return;if(file.size>3000000){toast(t('備份檔案過大。','Backup file is too large.'));return;}try{const data=JSON.parse(await file.text());if(!['TeachWithWhy','Evidence to Classroom'].includes(data.product)||!Array.isArray(data.records)||data.records.length>200||!data.records.every(validImport))throw Error();const ids=new Set(records.map(r=>r.id)),newItems=data.records.filter(r=>!ids.has(r.id));const old=records;records=[...newItems,...records];if(persist()){navigate('history');toast(t(`已匯入 ${newItems.length} 個新紀錄；相同編號保留現有版本。`,`Imported ${newItems.length} new records; existing IDs were kept.`));}else records=old;}catch{toast(t('備份格式不正確，沒有修改現有紀錄。','Invalid backup. Existing records were not changed.'));}}
function bindForms(){const f=$('#class-form');if(f)f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;capture();if(!draft.problem.trim()||!draft.goal.trim()){toast(errorText('INVALID_INPUT'));return;}navigate('compare');});const a=$('#access-form');if(a)a.addEventListener('submit',e=>{e.preventDefault();sessionStorage.setItem('etc-pilot-code',$('#access-code').value.trim());toast(t('試用碼已儲存在本次工作階段。','Pilot code saved for this session.'));});const r=$('#reflection-form');if(r)r.addEventListener('submit',e=>{e.preventDefault();if(saveReflection()){toast(t('回顧已儲存。','Reflection saved.'));navigate('history');}});$('#import-file')?.addEventListener('change',e=>importRecords(e.target.files[0]));}
function switchLanguage(){
 const previousLang=lang,previousView=view,scrollY=window.scrollY;
 if(view==='create')capture();
 if(view==='plan')syncPlan();
 const reflectionForm=$('#reflection-form');
 const reflectionDraft=reflectionForm?Object.fromEntries(new FormData(reflectionForm)):null;
 const participationIndex=$('#participation')?.selectedIndex;
 en=!en;lang=en?'en':'zh';
 names=translate_names();exampleProblems=translate_exampleProblems();exampleGoals=translate_exampleGoals();
 const subjectIndex=subjects[previousLang].indexOf(draft.subject);
 if(subjectIndex>=0)draft.subject=subjects[lang][subjectIndex];
 try{localStorage.setItem('teachwithwhy-ui-language',lang);}catch{}
 shell();navigate(previousView,false);
 if(reflectionDraft){const form=$('#reflection-form');for(const [key,value]of Object.entries(reflectionDraft)){const input=form?.elements.namedItem(key);if(input&&key!=='participation')input.value=value;}if($('#participation'))$('#participation').selectedIndex=participationIndex;}
 window.scrollTo({top:scrollY,behavior:'instant'});
}
document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-language]');if(!el)return;if(busy){e.preventDefault();toast(t('正在檢索與生成，請稍候。','Searching and generating. Please wait.'));return;}if(el.matches('[data-language]')){e.preventDefault();switchLanguage();return;}if(el.dataset.nav){if(view==='create')capture();if(view==='plan')syncPlan();navigate(el.dataset.nav);return;}if(el.dataset.example!==undefined){const i=Number(el.dataset.example);draft={...blank(),strategy:strategies[i].id,problem:exampleProblems[i],goal:exampleGoals[i]};plan=null;activeId=null;navigate('create');return;}if(el.dataset.guideExample){const junior=el.dataset.guideExample==='junior';draft={...blank(),level:el.dataset.guideExample,subject:subjects[lang][junior?3:0],students:junior?32:30,minutes:junior?15:12,topic:junior?t('比較兩個科學解釋','Comparing two scientific explanations'):t('故事人物的選擇','A character’s choices'),strategy:junior?'reason':'think',goal:junior?t('比較兩個解釋，指出各自依據及未知之處。','Compare two explanations, identify their evidence and note uncertainty.'):t('每人先提出想法，再用一個理由解釋人物的選擇。','Each pupil prepares an idea and a reason for a character’s choice.')};activeId=null;plan=null;navigate('create');return;}if(el.dataset.source){showSource(el.dataset.source);return;}if(el.dataset.ai){generate(el.dataset.ai);return;}if(el.dataset.sample){draft.strategy=el.dataset.sample;plan=samplePlan(draft,lang);activeId=null;navigate('plan');return;}if(el.dataset.open){open(el.dataset.open);return;}if(el.dataset.review){open(el.dataset.review,'reflect');return;}if(el.dataset.delete){if(confirm(t('刪除此活動及回顧？無法復原，建議先下載備份。','Delete this activity and reflection? This cannot be undone; download a backup first.'))){const prev=records;records=records.filter(r=>r.id!==el.dataset.delete);if(persist())navigate('history');else records=prev;}return;}switch(el.dataset.action){case'new':draft=blank();plan=null;activeId=null;navigate('create');break;case'save':save();break;case'reflect':if(save(true))navigate('reflect');break;case'reflect-ai':reflectAI();break;case'export':exportRecords();break;case'print':syncPlan();document.querySelectorAll('[data-step]').forEach(x=>x.nextElementSibling.textContent=x.value);$('#teacher-note').nextElementSibling.textContent=plan.teacherNote;window.print();break;case'clear-code':sessionStorage.removeItem('etc-pilot-code');$('#access-code').value='';toast(t('已清除。','Cleared.'));break;case'refresh-status':checkStatus();break;}});
shell();try{const s=JSON.parse(sessionStorage.getItem('etc-language-state')||'null');if(s?.draft){draft=s.draft;plan=s.plan;activeId=s.activeId;view=Object.hasOwn(names,s.view)?s.view:'home';sessionStorage.removeItem('etc-language-state');}}catch{}
navigate(view,false);checkStatus();
